# Code Generated by Sidekick is for learning and experimentation purposes only.
# filename: scripts/close_case.py
"""C5: an analyst closes a case as fraud / not_fraud. Every step is safe to repeat: after a crash, rerun it.
  python -m scripts.close_case --list
  python -m scripts.close_case "<case_id>" fraud --analyst a.analyst
"""
import argparse, json, os, re, time

from botocore.exceptions import ClientError

from common.aws import client, resource
from scripts.check import scan_all

BUCKET = os.environ.get("LABEL_BUCKET", "fraud-labels")
OUTCOMES = ("fraud", "not_fraud")
CASE_ID_RE = re.compile(r"[A-Za-z0-9_-]{4,64}#\d{10,16}")    # real cases only, never card#... / evt#... rows
ANALYST_RE = re.compile(r"[A-Za-z0-9._-]{2,40}")


class CloseRefused(Exception):
    """The case doesn't exist, or it is already closed with a DIFFERENT outcome."""


def valid_case_id(s):
    return bool(CASE_ID_RE.fullmatch(s or ""))


def _condition_failed(e):
    return e.response["Error"]["Code"] == "ConditionalCheckFailedException"


def close(cases, case_id, outcome, analyst, now):
    """Step 1: OPEN -> CLOSED, or a rerun with the SAME outcome. ALL_NEW returns txn_ids at the exact moment
    of closing; from then on, case_creator's 'only if OPEN' condition stops new payments joining."""
    try:
        r = cases.update_item(
            Key={"case_id": case_id},
            UpdateExpression="SET #st = :closed, #oc = :o, closed_by = if_not_exists(closed_by, :a), "
                             "closed_at = if_not_exists(closed_at, :n)",      # a rerun keeps the first values
            ConditionExpression="attribute_exists(txn_ids) AND (#st = :open OR (#st = :closed AND #oc = :o))",
            ExpressionAttributeNames={"#st": "status", "#oc": "outcome"},
            ExpressionAttributeValues={":closed": "CLOSED", ":open": "OPEN", ":o": outcome,
                                       ":a": analyst, ":n": int(now)},
            ReturnValues="ALL_NEW")
    except ClientError as e:
        if _condition_failed(e):
            raise CloseRefused(case_id) from None
        raise
    return r["Attributes"]


def release_pointer(cases, token, case_id):
    """Step 2: delete card#<token> only if it still points at THIS case (a newer case keeps its pointer)."""
    try:
        cases.delete_item(Key={"case_id": f"card#{token}"}, ConditionExpression="open_case_id = :id",
                          ExpressionAttributeValues={":id": case_id})
    except ClientError as e:
        if not _condition_failed(e):
            raise                                   # condition failed = pointer gone or newer: nothing to do


def write_label(s3, case):
    """Step 3: the human label for training. Values come from the stored case, so a rerun writes the same file."""
    body = {"case_id": case["case_id"], "card_token": case["card_token"], "outcome": case["outcome"],
            "txn_ids": sorted(case["txn_ids"]), "closed_by": case["closed_by"],
            "closed_at": int(case["closed_at"]), "label_source": "analyst"}
    s3.put_object(Bucket=BUCKET, Key=f"dispositions/{case['case_id'].replace('#', '_')}.json",
                  Body=json.dumps(body).encode())


def list_open(cases):
    rows = sorted((c for c in scan_all(cases) if "txn_ids" in c and c.get("status") == "OPEN"),
                  key=lambda c: c["case_id"])
    for c in rows:
        print(f"{c['case_id']}  payments={len(c['txn_ids'])}  last={c.get('last_decision')}  "
              f"score={c.get('last_score')}")
    print(f"{len(rows)} open case(s)")


def main():
    p = argparse.ArgumentParser(description="Close a fraud case")
    p.add_argument("case_id", nargs="?")
    p.add_argument("outcome", nargs="?")
    p.add_argument("--analyst", default="")
    p.add_argument("--list", action="store_true", help="show OPEN cases and exit")
    a = p.parse_args()
    cases = resource("dynamodb").Table("cases")
    if a.list:
        return list_open(cases)
    if not valid_case_id(a.case_id) or a.outcome not in OUTCOMES or not ANALYST_RE.fullmatch(a.analyst):
        p.error("usage: <case_id> fraud|not_fraud --analyst <id>   (or --list)")
    try:
        case = close(cases, a.case_id, a.outcome, a.analyst, time.time())
    except CloseRefused:
        raise SystemExit("refused: no such case, or it is already closed with a different outcome")
    release_pointer(cases, case["card_token"], a.case_id)
    write_label(client("s3"), case)
    print(f"closed {a.case_id} as {a.outcome} ({len(case['txn_ids'])} payments)")


if __name__ == "__main__":
    main()
